original.header:
private theorem smoothFrame_identity_on_upper (N : ℕ) [NeZero N] (hN : 0 < N)
    (Phi : UpperHalfPlane → ℂ) {p : ℝ × ℝ} (hp : p ∈ upperChart) :
    smoothFrame N (1 : SL(2, ℤ)) Phi p = extendUpper Phi p

